$("#save-telegram-settings").on("click",function(){const e=App.Utils.Url.siteUrl("telegram/save_settings");$.post(e,{csrf_token:vars("csrf_token"),bot_token:$("#bot-token").val(),notifications_enabled:$("#notifications-enabled").is(":checked")?1:0}).done(e=>{App.Layouts.Backend.displayNotification("Telegram ayarları kaydedildi."),e.bot_username&&location.reload()}).fail(e=>{App.Layouts.Backend.displayNotification(e.responseJSON?.message||"Kaydedilemedi.")})}),$("#setup-webhook").on("click",function(){const e=App.Utils.Url.siteUrl("telegram/setup_webhook");$.post(e,{csrf_token:vars("csrf_token")}).done(()=>{App.Layouts.Backend.displayNotification("Webhook kuruldu."),location.reload()}).fail(e=>{App.Layouts.Backend.displayNotification(e.responseJSON?.message||"Webhook kurulamadı.")})}),$(document).on("click",".generate-link-btn",function(){const e=$(this).data("user-id"),t=App.Utils.Url.siteUrl("telegram/generate_link");$.post(t,{csrf_token:vars("csrf_token"),user_id:e}).done(e=>{App.Utils.Message.show("Bağlantı Linki",'<p>Bu linki personele iletin, bota "Başlat"a bastıklarında Telegram hesapları bağlanır:</p><input type="text" class="form-control" readonly value="'+e.link+'" onclick="this.select()">')}).fail(e=>{App.Layouts.Backend.displayNotification(e.responseJSON?.message||"Link oluşturulamadı.")})}),$(document).on("click",".reply-btn",function(){const e=$(this),t=e.closest(".input-group").find(".reply-input"),a=t.val().trim();if(!a)return;const i=App.Utils.Url.siteUrl("telegram/reply");$.post(i,{csrf_token:vars("csrf_token"),chat_id:e.data("chat-id"),user_id:e.data("user-id")||null,message:a}).done(()=>{App.Layouts.Backend.displayNotification("Mesaj gönderildi."),t.val("")}).fail(e=>{App.Layouts.Backend.displayNotification(e.responseJSON?.message||"Gönderilemedi.")})});